contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        // fund c via Command with empty data (triggers receive on c)
        c.Command{value: amount}(address(c), ""); if (__ESBMC_reverted()) return;
        require(address(c).balance == amount);
        uint ownerBefore = address(this).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(c).balance == 0 && address(this).balance == ownerBefore + amount);
    }
    receive() external payable {}
}

